# ============================================================
# MINES GAME STATE
# ============================================================

class MinesGame:
    def __init__(
        self,
        bot: "CasinoBot",
        user_id: int,
        amount: Decimal,
        mines: int,
        game_id: int,
        server_hash: str,
        server_seed: str,
        client_seed: str,
        nonce: int,
    ):

        self.bot = bot
        self.user_id = user_id
        self.amount = amount
        self.mines = mines
        self.game_id = game_id

        self.server_hash = server_hash
        self.server_seed = server_seed
        self.client_seed = client_seed
        self.nonce = nonce

        # Mines are derived from the committed server seed, not Python's random module.
        positions = list(range(25))
        positions = bot.fair_shuffle(
            positions, server_seed, client_seed, nonce, "mines"
        )
        self.bombs = set(positions[:mines])

        self.opened: set[int] = set()
        self.finished = False

    @property
    def multiplier(self) -> Decimal:

        opened = len(self.opened)

        if opened <= 0:
            return Decimal("1.00")

        value = (
            Decimal("25")
            / Decimal(str(25 - self.mines))
        ) ** opened

        value *= Decimal("0.96")

        return value.quantize(
            Decimal("0.01"),
            rounding=ROUND_DOWN,
        )

    @property
    def payout(self) -> Decimal:
        return (
            self.amount * self.multiplier
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_DOWN,
        )


class MinesView(CasinoV2View):
    def __init__(self, game: MinesGame):
        super().__init__(timeout=300)
        self.game = game
        self.header_text = discord.ui.TextDisplay(f"> ﹒**{game.mines}** mines on a 5×5 board · more mines = bigger multiplier\n> ﹒**{len(game.opened)}** safe tiles · current **{game.multiplier:.2f}×**")
        self.header = discord.ui.Container(
            discord.ui.TextDisplay(f"## Mines — {money(game.amount)} Bet"),
            self.header_text,
            discord.ui.Separator(visible=True),
            accent_color=0x7C4DFF,
        )
        self.add_item(self.header)
        self.rows = []
        for row_index in range(5):
            row = discord.ui.ActionRow()
            for col_index in range(5):
                index = row_index * 5 + col_index
                if index >= 25:
                    button = discord.ui.Button(label="·", style=discord.ButtonStyle.secondary, disabled=True)
                else:
                    button = discord.ui.Button(label="?", style=discord.ButtonStyle.secondary, custom_id=f"mine:{index}")
                    button.callback = self.make_callback(index)
                row.add_item(button)
            self.add_item(row)
            self.rows.append(row)
        cashout = discord.ui.Button(label="Cashout", style=discord.ButtonStyle.success, custom_id="mine_cashout")
        cashout.callback = self.cashout
        self.cashout_row = discord.ui.ActionRow(cashout)
        self.add_item(self.cashout_row)
        self.refresh_container()

    def _buttons(self):
        for child in self.walk_children():
            if isinstance(child, discord.ui.Button):
                yield child

    def refresh_container(self):
        self.header_text.content = (
            f"> ﹒**{self.game.mines}** mines on a 5×5 board · more mines = bigger multiplier\n"
            f"> ﹒**{len(self.game.opened)}** safe tiles · current **{self.game.multiplier:.2f}×**"
        )

    def make_callback(self, index: int):
        async def callback(interaction: discord.Interaction):
            if interaction.user.id != self.game.user_id:
                await interaction.response.send_message("This Mines game belongs to another player.", ephemeral=True)
                return
            await self.game.bot.mines_click(interaction, self.game, index, self)
        return callback

    async def cashout(self, interaction: discord.Interaction):
        if interaction.user.id != self.game.user_id:
            await interaction.response.send_message("This Mines game belongs to another player.", ephemeral=True)
            return
        await self.game.bot.mines_cashout(interaction, self.game, self)

    def add_header(self):
        # Action rows cannot be nested in a Container, so the board is the main V2 layout.
        pass


def mines_result_v2(game: MinesGame, result_label: str, payout: Decimal, multiplier: Decimal):
    won = payout > 0
    net = payout - game.amount
    sign = "+" if net >= 0 else "-"
    accent = 0x57F287 if won else 0xED4245
    text = (
        f"## {'WIN' if won else 'LOSE'}\n\n"
        f"> ﹒{game.bot.get_user(game.user_id).display_name if game.bot.get_user(game.user_id) else 'Player'} · **{'+' if won else '-'}{money(payout if won else game.amount)} (`{sign}{money(abs(net))}` net)** at `{multiplier:.4f}×` · mines · **{game.mines} mines** · **{len(game.opened)}** · **{multiplier:.2f}×** · stake `{money(game.amount)}`\n\n"
        f"`Bet ID {game.game_id}` · hit a big one? drop a vouch"
    )
    view = CasinoV2View(timeout=300)
    view.add_item(discord.ui.Container(discord.ui.TextDisplay(text), accent_color=accent))
    return view


