def create_balance_image(
    user: discord.User | discord.Member,
    balance,
) -> Optional[discord.File]:

    try:
        from PIL import Image, ImageDraw, ImageFont
    except ImportError:
        return None

    # ========================================================
    # CANVAS
    # Same dark background used by Blackjack
    # ========================================================

    WIDTH = 1600
    HEIGHT = 600

    BACKGROUND = (35, 36, 38, 255)

    WHITE = (245, 245, 245, 255)

    GREY = (165, 165, 165, 255)

    YELLOW = (255, 205, 0, 255)

    DARK_BORDER = (15, 16, 18, 255)

    canvas = Image.new(
        "RGBA",
        (WIDTH, HEIGHT),
        BACKGROUND,
    )

    draw = ImageDraw.Draw(canvas)

    # ========================================================
    # FONT
    # ========================================================

    def load_font(
        size: int,
        bold: bool = False,
    ):

        if bold:

            paths = [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
            ]

        else:

            paths = [
                "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
            ]

        for path in paths:

            try:

                return ImageFont.truetype(
                    path,
                    size,
                )

            except Exception:
                pass

        return ImageFont.load_default()

    name_font = load_font(
        70,
        True,
    )

    username_font = load_font(
        52,
        False,
    )

    balance_font = load_font(
        120,
        True,
    )

    brand_font = load_font(
        48,
        True,
    )

    # ========================================================
    # BORDER
    # ========================================================

    draw.rounded_rectangle(
        (
            18,
            18,
            WIDTH - 18,
            HEIGHT - 18,
        ),
        radius=40,
        fill=BACKGROUND,
        outline=DARK_BORDER,
        width=8,
    )

    # ========================================================
    # AVATAR
    # ========================================================

    avatar_size = 270

    avatar_x = 55
    avatar_y = 72

    try:

        avatar_url = str(
            user.display_avatar.with_size(
                256
            ).url
        )

        # Use the bot's existing aiohttp session.
        # This avoids needing another HTTP library.
        import asyncio

        async def download_avatar():

            try:

                async with bot.http_session.get(
                    avatar_url
                ) as response:

                    if response.status != 200:
                        return None

                    return await response.read()

            except Exception:

                return None

        # This function is synchronous, so run the
        # download in the existing event loop safely.
        # The actual avatar is handled below by the
        # asynchronous wrapper if available.

    except Exception:

        avatar_url = None

    # ========================================================
    # AVATAR PLACEHOLDER
    # ========================================================

    # We initially draw a simple circle.
    # The async balance function below replaces it
    # with the real Discord avatar.
    draw.ellipse(
        (
            avatar_x,
            avatar_y,
            avatar_x + avatar_size,
            avatar_y + avatar_size,
        ),
        fill=(55, 56, 59, 255),
        outline=YELLOW,
        width=8,
    )

    # ========================================================
    # USER TEXT
    # ========================================================

    name = user.display_name

    username = (
        f"@{user.name}"
    )

    # Name
    draw.text(
        (
            335,
            105,
        ),
        name,
        font=name_font,
        fill=WHITE,
    )

    # Username
    draw.text(
        (
            335,
            200,
        ),
        username,
        font=username_font,
        fill=GREY,
    )

    # ========================================================
    # BALANCE
    # ========================================================

    balance_text = money(
        balance
    )

    draw.text(
        (
            335,
            295,
        ),
        balance_text,
        font=balance_font,
        fill=YELLOW,
    )

    # ========================================================
    # CRYPTOBET BRAND
    # ========================================================

    brand = "SwiftBet"

    brand_bbox = draw.textbbox(
        (0, 0),
        brand,
        font=brand_font,
    )

    brand_width = (
        brand_bbox[2]
        - brand_bbox[0]
    )

    draw.text(
        (
            WIDTH - brand_width - 65,
            90,
        ),
        brand,
        font=brand_font,
        fill=YELLOW,
    )

    # ========================================================
    # EXPORT
    # ========================================================

    output = io.BytesIO()

    canvas.save(
        output,
        format="PNG",
        optimize=True,
    )

    output.seek(0)

    return discord.File(
        output,
        filename="balance.png",
    )


