# ============================================================
# BALANCE IMAGE
# ============================================================

def create_balance_font(
    size: int,
    bold: bool = False,
):
    """
    Load a real scalable TTF font.
    Searches common Linux font locations so Railway
    does not fall back to Pillow's tiny default font.
    """

    font_candidates = []

    if bold:
        font_candidates = [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
        ]
    else:
        font_candidates = [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
        ]

    # Try known paths first
    for font_path in font_candidates:

        try:

            if Path(font_path).exists():

                return ImageFont.truetype(
                    font_path,
                    size,
                )

        except Exception:
            pass

    # Search system fonts as a fallback
    try:

        font_root = Path(
            "/usr/share/fonts"
        )

        if font_root.exists():

            all_fonts = list(
                font_root.rglob("*.ttf")
            )

            if bold:

                preferred = [
                    p
                    for p in all_fonts
                    if "bold" in p.name.lower()
                ]

            else:

                preferred = [
                    p
                    for p in all_fonts
                    if "bold" not in p.name.lower()
                ]

            search_fonts = (
                preferred
                if preferred
                else all_fonts
            )

            for font_path in search_fonts:

                try:

                    return ImageFont.truetype(
                        str(font_path),
                        size,
                    )

                except Exception:
                    continue

    except Exception:
        pass

    # Pillow versions with scalable default font support
    try:

        return ImageFont.load_default(
            size=size
        )

    except Exception:

        return ImageFont.load_default()


