async def get_crypto_usd_price(currency: str) -> Optional[Decimal]:
    """Fetch a current USD price for the requested withdrawal coin."""
    currency = currency.upper()
    symbols = {"LTC": "LTCUSDT", "SOL": "SOLUSDT"}
    if currency == "USDT":
        return Decimal("1")
    if currency not in symbols:
        return None

    urls = [
        f"https://api.binance.com/api/v3/ticker/price?symbol={symbols[currency]}",
        f"https://api.coingecko.com/api/v3/simple/price?ids={'litecoin' if currency == 'LTC' else 'solana'}&vs_currencies=usd",
    ]

    session = getattr(bot, "http_session", None)
    if session is None:
        session = aiohttp.ClientSession()
        temporary = True
    else:
        temporary = False

    try:
        for url in urls:
            try:
                async with session.get(url, timeout=aiohttp.ClientTimeout(total=8)) as response:
                    if response.status != 200:
                        continue
                    data = await response.json()
                    if "binance" in url:
                        price = Decimal(str(data.get("price", "0")))
                    else:
                        coin_id = "litecoin" if currency == "LTC" else "solana"
                        price = Decimal(str(data.get(coin_id, {}).get("usd", "0")))
                    if price > 0:
                        return price
            except Exception:
                continue
    finally:
        if temporary:
            await session.close()

    return None


async def create_withdrawal_request(self, user_id: int, currency: str, address: str, amount, fee=Decimal("0"), owner_override: bool=False):
    amount=Decimal(str(amount)); fee=Decimal(str(fee)); total=amount+fee
    async with self.pool.acquire() as conn:
        async with conn.transaction():
            if owner_override:
                row=await conn.fetchrow("SELECT balance FROM users WHERE user_id=$1", user_id)
                balance_after=row["balance"] if row else Decimal("0")
            else:
                row=await conn.fetchrow("""UPDATE users SET balance=balance-$2, lifetime_withdraw=lifetime_withdraw+$2, updated_at=NOW() WHERE user_id=$1 AND frozen=FALSE AND balance >= $2 RETURNING balance""", user_id,total)
                if not row: return None
                balance_after=row["balance"]
            wid=await conn.fetchval("""INSERT INTO withdrawals(user_id,currency,address,amount,fee,status,owner_override) VALUES($1,$2,$3,$4,$5,'pending',$6) RETURNING id""",user_id,currency.upper(),address,amount,fee,owner_override)
            if not owner_override:
                await conn.execute("""INSERT INTO transactions(user_id,kind,amount,balance_after,note) VALUES($1,'withdraw',$2,$3,$4)""",user_id,-total,balance_after,f"{currency.upper()} withdrawal #{wid}")
            return int(wid)

Database.create_withdrawal_request = create_withdrawal_request


class WithdrawalAdminView(discord.ui.View):
    def __init__(self, bot_instance: "CasinoBot", withdrawal_id: int):
        super().__init__(timeout=None)
        self.bot = bot_instance
        self.withdrawal_id = int(withdrawal_id)

        self.accept_button = discord.ui.Button(
            label="Accept",
            style=discord.ButtonStyle.success,
            custom_id=f"withdraw_accept:{self.withdrawal_id}",
        )
        self.decline_button = discord.ui.Button(
            label="Decline",
            style=discord.ButtonStyle.danger,
            custom_id=f"withdraw_decline:{self.withdrawal_id}",
        )
        self.accept_button.callback = self.accept
        self.decline_button.callback = self.decline
        self.add_item(self.accept_button)
        self.add_item(self.decline_button)

    async def _admin_check(self, interaction: discord.Interaction) -> bool:
        admin_ids = set(getattr(config, "ADMIN_USER_IDS", []) or [])
        owner_id = getattr(config, "OWNER_ID", None)
        try:
            if owner_id is not None:
                admin_ids.add(int(owner_id))
        except (TypeError, ValueError):
            pass
        if interaction.user.id not in admin_ids:
            await interaction.response.send_message(
                embed=error_embed(
                    "Permission Denied",
                    "Only a bot administrator can manage withdrawals.",
                ),
                ephemeral=True,
            )
            return False
        return True

    async def _get_row(self):
        return await self.bot.db.pool.fetchrow(
            """
            SELECT id, user_id, currency, address, amount, fee, status, owner_override, created_at
            FROM withdrawals
            WHERE id=$1
            """,
            self.withdrawal_id,
        )

    async def accept(self, interaction: discord.Interaction):
        if not await self._admin_check(interaction):
            return

        row = await self._get_row()
        if not row:
            await interaction.response.send_message("Withdrawal not found.", ephemeral=True)
            return
        if str(row["status"]).lower() != "pending":
            await interaction.response.send_message(
                f"This withdrawal is already `{row['status']}`.",
                ephemeral=True,
            )
            return

        currency = str(row["currency"]).upper()
        amount = Decimal(str(row["amount"]))
        reserve_column = {"LTC":"ltc_balance", "SOL":"sol_balance", "USDT":"usdt_balance"}.get(currency)
        if reserve_column is None:
            await interaction.response.send_message("Unsupported withdrawal currency.", ephemeral=True); return
        async with self.bot.db.pool.acquire() as conn:
            async with conn.transaction():
                locked=await conn.fetchrow("SELECT * FROM withdrawals WHERE id=$1 FOR UPDATE", self.withdrawal_id)
                if not locked or str(locked["status"]).lower() != "pending":
                    await interaction.response.send_message("This withdrawal was already processed.", ephemeral=True); return
                reserve=await conn.fetchrow(f"UPDATE house SET {reserve_column}={reserve_column}-$1, balance=balance-$1 WHERE id=1 AND {reserve_column}>=$1 AND balance>=$1 RETURNING {reserve_column},balance", amount)
                if not reserve:
                    await interaction.response.send_message(embed=error_embed("Insufficient House Balance", f"The house does not have enough **{currency}** reserve to approve this withdrawal."), ephemeral=True); return
                await conn.execute("UPDATE withdrawals SET status='approved', processed_at=NOW() WHERE id=$1", self.withdrawal_id)

        user = self.bot.get_user(int(row["user_id"]))
        crypto_price = await get_crypto_usd_price(str(row["currency"]))
        crypto_amount = (
            (Decimal(str(row["amount"])) / crypto_price).quantize(Decimal("0.00000001"))
            if crypto_price and crypto_price > 0
            else None
        )
        crypto_text = (
            f"({crypto_amount:.8f} {row['currency'].upper()})"
            if crypto_amount is not None
            else f"({row['currency'].upper()} amount unavailable)"
        )

        if user:
            try:
                await user.send(
                    embed=success_embed(
                        "Withdrawal Approved",
                        (
                            f"Your withdrawal of **{money(Decimal(str(row['amount'])))} USD** "
                            f"{crypto_text} has been **approved**.\n\n"
                            "An admin will send the funds to your wallet."
                        ),
                    )
                )
            except Exception as exc:
                print(f"[WITHDRAW] User DM failed: {exc}")

        self.accept_button.disabled = True
        self.decline_button.disabled = True
        await interaction.response.edit_message(
            embed=base_embed(
                "SwiftBet Withdrawal — Approved",
                (
                    f"**User:** <@{row['user_id']}>\n"
                    f"**Amount:** {money(Decimal(str(row['amount'])))} USD {crypto_text}\n"
                    f"**Currency:** `{row['currency'].upper()}`\n"
                    f"**Address:** `{row['address']}`\n"
                    f"**Approved by:** {interaction.user.mention}\n\n"
                    "**Status:** `Approved — Pay the user manually`"
                ),
            ),
            view=self,
        )

    async def decline(self, interaction: discord.Interaction):
        if not await self._admin_check(interaction):
            return

        row = await self._get_row()
        if not row:
            await interaction.response.send_message("Withdrawal not found.", ephemeral=True)
            return
        if str(row["status"]).lower() != "pending":
            await interaction.response.send_message(
                f"This withdrawal is already `{row['status']}`.",
                ephemeral=True,
            )
            return

        async with self.bot.db.pool.acquire() as conn:
            async with conn.transaction():
                locked = await conn.fetchrow(
                    "SELECT * FROM withdrawals WHERE id=$1 FOR UPDATE",
                    self.withdrawal_id,
                )
                if not locked or str(locked["status"]).lower() != "pending":
                    await interaction.response.send_message(
                        "This withdrawal was already processed.",
                        ephemeral=True,
                    )
                    return

                amount = Decimal(str(locked["amount"]))
                await conn.execute(
                    """
                    UPDATE withdrawals
                    SET status='declined', processed_at=NOW()
                    WHERE id=$1
                    """,
                    self.withdrawal_id,
                )
                if not bool(locked.get("owner_override", False)):
                    balance_after = await conn.fetchval("""UPDATE users SET balance=balance+$2, lifetime_withdraw=GREATEST(0,lifetime_withdraw-$2), updated_at=NOW() WHERE user_id=$1 RETURNING balance""", int(locked["user_id"]), amount)
                    await conn.execute("""INSERT INTO transactions(user_id,kind,amount,balance_after,note) VALUES($1,'withdraw_refund',$2,$3,$4)""", int(locked["user_id"]), amount,balance_after,f"Declined withdrawal #{self.withdrawal_id}")

        user = self.bot.get_user(int(row["user_id"]))
        if user:
            try:
                await user.send(
                    embed=error_embed(
                        "Withdrawal Declined",
                        (
                            f"Your withdrawal of **{money(Decimal(str(row['amount'])))} USD** "
                            "was declined by an admin.\n\n"
                            "The withdrawal amount has been returned to your balance."
                        ),
                    )
                )
            except Exception as exc:
                print(f"[WITHDRAW] User DM failed: {exc}")

        self.accept_button.disabled = True
        self.decline_button.disabled = True
        await interaction.response.edit_message(
            embed=base_embed(
                "SwiftBet Withdrawal — Declined",
                (
                    f"**User:** <@{row['user_id']}>\n"
                    f"**Amount:** {money(Decimal(str(row['amount'])))}\n"
                    f"**Currency:** `{row['currency'].upper()}`\n"
                    f"**Address:** `{row['address']}`\n"
                    f"**Declined by:** {interaction.user.mention}\n\n"
                    "**Status:** `Declined — Amount refunded`"
                ),
            ),
            view=self,
        )


