def parse_rain_duration(raw: str):
    """Parse rain duration such as 30s, 1m, 5m, or 1h."""
    text = str(raw).strip().lower()
    if not text:
        return None

    units = {
        "s": 1,
        "sec": 1,
        "secs": 1,
        "second": 1,
        "seconds": 1,
        "m": 60,
        "min": 60,
        "mins": 60,
        "minute": 60,
        "minutes": 60,
        "h": 3600,
        "hr": 3600,
        "hrs": 3600,
        "hour": 3600,
        "hours": 3600,
    }

    if text.isdigit():
        # Bare numbers are treated as minutes for convenience.
        seconds = int(text) * 60
    else:
        match = re.fullmatch(r"(\d+(?:\.\d+)?)\s*([a-z]+)", text)
        if not match:
            return None
        value = Decimal(match.group(1))
        multiplier = units.get(match.group(2))
        if multiplier is None:
            return None
        seconds = int(value * multiplier)

    if seconds < 10 or seconds > 86400:
        return None
    return seconds


@prefix_command(name="rain")
async def rain_command(
    interaction: discord.Interaction,
    amount: str,
    duration: str,
):

    # --------------------------------------------------------
    # PARSE AMOUNT
    # --------------------------------------------------------

    bet = normalize_amount(
        amount
    )

    if bet is None:

        await bot.safe_send(
            interaction,
            content="Enter a valid rain amount.",
            ephemeral=True,
        )

        return

    if bet <= Decimal("0"):

        await bot.safe_send(
            interaction,
            content="Rain amount must be greater than 0.",
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # PARSE DURATION
    # --------------------------------------------------------

    seconds = parse_rain_duration(duration)

    if seconds is None:
        await bot.safe_send(
            interaction,
            content=(
                "Enter a valid rain time. Examples: `30s`, `1m`, `5m`. "
                "Duration must be between 10 seconds and 24 hours."
            ),
            ephemeral=True,
        )
        return

    # --------------------------------------------------------
    # CHECK BALANCE
    # --------------------------------------------------------

    balance = await bot.get_balance(
        interaction.user.id
    )

    if bet > balance:

        await bot.safe_send(
            interaction,
            content=(
                "You Dont Have Enough Crypto\n"
                "-# use /deposit to top-up Funds"
            ),
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # DEDUCT RAIN AMOUNT
    # --------------------------------------------------------

    deducted = await bot.db.change_balance(
        interaction.user.id,
        -bet,
        kind="rain_start",
        note="rain",
    )

    if not deducted:

        await bot.safe_send(
            interaction,
            content=(
                "Your balance changed. "
                "Please try again."
            ),
            ephemeral=True,
        )

        return

    # --------------------------------------------------------
    # CREATE RAIN
    # --------------------------------------------------------

    rain_id = secrets.token_hex(8)

    bot.active_rains[rain_id] = {
        "amount": bet,
        "user_id": interaction.user.id,
        "owner_mention": interaction.user.mention,
        "channel_id": interaction.channel_id,
        "players": set(),
    }

    # --------------------------------------------------------
    # SEND RAIN MESSAGE
    # --------------------------------------------------------

    try:

        await interaction.response.send_message(
            f"## Rain Started — **{money(bet)}**\n"
            f"**{interaction.user.mention}** rained — "
            f"**{money(bet)}**\n\n"
            "Click the button below to join.",
            view=RainView(
                bot,
                rain_id,
            ),
        )

    except Exception as e:

        print(
            f"[RAIN] Failed to send rain message: {e}"
        )

        bot.active_rains.pop(
            rain_id,
            None,
        )

        try:

            await bot.db.change_balance(
                interaction.user.id,
                bet,
                kind="rain_refund",
                note=rain_id,
            )

        except Exception as refund_error:

            print(
                f"[RAIN] Failed to refund rain: {refund_error}"
            )

        return

    # --------------------------------------------------------
    # START TIMER
    # --------------------------------------------------------

    asyncio.create_task(
        rain_timer(
            bot,
            rain_id,
            seconds,
        )
    )


async def rain_timer(
    bot_instance: CasinoBot,
    rain_id: str,
    seconds: int,
):

    try:

        await asyncio.sleep(
            seconds
        )

        await bot_instance.finish_rain(
            rain_id
        )

    except asyncio.CancelledError:

        return

    except Exception as e:

        print(
            f"[RAIN] Timer error for {rain_id}: {e}"
        )
