@prefix_command(name="code")
@owner_only()
async def code_command(
    interaction: discord.Interaction,
    amount: str,
    max_uses: int,
    requirement: int,
):

    balance = await bot.get_balance(interaction.user.id)
    value = amount_or_all(amount, balance)

    if value is None:

        await interaction.response.send_message(
            "Invalid amount.",
            ephemeral=False,
        )

        return

    if max_uses <= 0:

        await interaction.response.send_message(
            "Max uses must be greater than zero.",
            ephemeral=False,
        )

        return

    if requirement not in CODE_REQUIREMENTS:

        await interaction.response.send_message(
            "Requirement must be 1, 2, or 3.",
            ephemeral=False,
        )

        return

    code = (
        "GOOSE-"
        + "".join(
            secrets.choice(
                string.ascii_uppercase
                + string.digits
            )
            for _ in range(8)
        )
    )

    await bot.db.pool.execute(
        """
        INSERT INTO codes(
            code,
            max_uses,
            amount
        )
        VALUES($1, $2, $3)
        """,
        code,
        max_uses,
        value,
    )

    requirement_data = CODE_REQUIREMENTS[
        requirement
    ]

    await interaction.response.send_message(
        embed=success_embed(
            "Promo Code Created",
            (
                f"**Code:** `{code}`\n"
                f"**Amount:** {money(value)} per person\n"
                f"**Max Uses:** {max_uses}\n"
                f"**Requirement:** "
                f"{requirement_data['name']}"
            ),
        ),
        ephemeral=False,
    )
